create temporary table desired_catalogue_sources on commit drop as select (jsonb_populate_record(null::public.catalogue_sources,(select jsonb_object_agg(k.value,p->'v'->((r.value->>(k.ordinality::int-1))::int)) from jsonb_array_elements_text(p->'c') with ordinality k(value,ordinality)))).* from (select '{"c":["id","set_id","source","purpose","url","notes"],"v":["2023-panini-immaculate-wwe-checklist","2023-panini-immaculate-wwe","Panini-format checklist / Checklist Insider mirror","Checklist","https://xcdn.checklistinsider.com/public/2024/06/2023-Panini-Immaculate-Collection-WWE-Wrestling-Checklist-Downloads-Excel-spreadsheet-new.xlsx","Older GTS export covers 2516 of 3362 editions. Additional 846 memorabilia editions independently reconcile to four published WrestlingTradingCards lists. Numeric source checklist numbers retained; physical codes not inferred.","2023-panini-immaculate-wwe-release","Checklist Insider","Release date","https://www.checklistinsider.com/2023-panini-immaculate-collection-wwe","2023 product label; actual hobby release in 2024.","2023-panini-immaculate-wwe-distributor","GTS Distribution / Panini","Original distributor checklist","https://gogts.net/wp-content/uploads/2024/06/2023-Panini-Immaculate-WWE-Trading-Cards-Checklist.xls","2023-panini-immaculate-wwe-comparison","Checklist Center","Independent checklist workbook","https://www.checklistcenter.com/2023-panini-immaculate-wwe-wrestling-card-checklist/","Chronicles all rows; Immaculate old export after combining separate signer rows and quote formatting.","2023-panini-immaculate-wwe-supplement","WrestlingTradingCards","Independent updated memorabilia identities and editions","https://wrestlingtradingcards.com/2023-wwe-panini-immaculate-collection-panini/","All four additional numbered lists and their declared caps/parallel statements reconcile to 846 exact rows.","2023-panini-chronicles-wwe-checklist","2023-panini-chronicles-wwe","https://xcdn.checklistinsider.com/public/2024/05/2023-Panini-Chronicles-WWE-Wrestling-Checklist-Downloads-Excel-Spreadsheet.xlsx","Both full workbook mirrors reconcile after three nickname quote differences. Original GTS updated workbook download did not complete; no origin-byte verification claimed. Missing source numbers remain missing.","2023-panini-chronicles-wwe-release","https://www.checklistinsider.com/2023-panini-chronicles-wwe-wrestling","2023-panini-chronicles-wwe-comparison","https://www.checklistcenter.com/2023-panini-chronicles-wwe-wrestling-card-checklist/","2023-panini-impeccable-wwe-checklist","2023-panini-impeccable-wwe","https://xcdn.checklistinsider.com/public/2024/03/2023-Panini-Impeccable-WWE-Wrestling-Checklist-Downloads-Excel-spreadsheet-checklist.xlsx","All 2335 original GTS rows match mirror after 19 occurrences of one Seth nickname encoding repair. Source base #36 absent. Parallel-only Indelible Ink Jerry Sags and Nova variants remain source-specific. April 3 final release calendar supersedes preliminary March 29.","2023-panini-impeccable-wwe-release","https://www.checklistinsider.com/2023-panini-impeccable-wwe","2023-panini-impeccable-wwe-distributor","https://gogts.net/wp-content/uploads/2024/03/2023-Panini-Impeccable-WWE-Trading-Cards-Checklist.xls","2023-panini-impeccable-wwe-release-final","GTS Distribution","Final release calendar","https://gogts.net/hot-in-the-shop-week-of-april-1-2024-phenomenal-multi-sport-week/","April 3, 2024 supersedes the preliminary March 29 checklist page schedule."],"r":[[0,1,2,3,4,5],[6,1,7,8,9,10],[11,1,12,13,14,5],[15,1,16,17,18,19],[20,1,21,22,23,24],[25,26,2,3,27,28],[29,26,7,8,30,10],[31,26,16,17,32,19],[33,34,2,3,35,36],[37,34,7,8,38,10],[39,34,12,13,40,36],[41,34,42,43,44,45]]}'::jsonb p) d cross join lateral jsonb_array_elements(p->'r') r(value);
do $$ begin
 if exists(select 1 from public.catalogue_sources t join desired_catalogue_sources e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from desired_catalogue_sources on conflict do nothing;
do $$ begin
 if (select count(*) from public.catalogue_sets where id='2023-panini-immaculate-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2023-panini-immaculate-wwe')<>35
 or (select count(*) from public.catalogue_cards where set_id='2023-panini-immaculate-wwe')<>1047
 or (select count(*) from public.catalogue_variants where set_id='2023-panini-immaculate-wwe')<>3362
 or (select count(*) from public.catalogue_parallel_rules where set_id='2023-panini-immaculate-wwe')<>165
 or (select count(*) from public.catalogue_sources where set_id='2023-panini-immaculate-wwe')<>5
 or (select count(*) from public.catalogue_sets where id='2023-panini-chronicles-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2023-panini-chronicles-wwe')<>34
 or (select count(*) from public.catalogue_cards where set_id='2023-panini-chronicles-wwe')<>843
 or (select count(*) from public.catalogue_variants where set_id='2023-panini-chronicles-wwe')<>5862
 or (select count(*) from public.catalogue_parallel_rules where set_id='2023-panini-chronicles-wwe')<>240
 or (select count(*) from public.catalogue_sources where set_id='2023-panini-chronicles-wwe')<>3
 or (select count(*) from public.catalogue_sets where id='2023-panini-impeccable-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2023-panini-impeccable-wwe')<>24
 or (select count(*) from public.catalogue_cards where set_id='2023-panini-impeccable-wwe')<>664
 or (select count(*) from public.catalogue_variants where set_id='2023-panini-impeccable-wwe')<>2335
 or (select count(*) from public.catalogue_parallel_rules where set_id='2023-panini-impeccable-wwe')<>130
 or (select count(*) from public.catalogue_sources where set_id='2023-panini-impeccable-wwe')<>4
 or (select count(*) from public.catalogue_sets)<>49
 or (select count(*) from public.catalogue_cards)<>25285
 or exists(select 1 from public.catalogue_variants v left join public.catalogue_cards c on c.id=v.card_id where v.set_id in ('2023-panini-immaculate-wwe','2023-panini-chronicles-wwe','2023-panini-impeccable-wwe') and (c.id is null or c.set_id<>v.set_id))
 or exists(select 1 from public.catalogue_subsets s where s.set_id in ('2023-panini-immaculate-wwe','2023-panini-chronicles-wwe','2023-panini-impeccable-wwe') and s.card_count<>(select count(*) from public.catalogue_cards c where c.set_id=s.set_id and c.subset_code=s.subset_code))
 or exists(select row from before_catalogue_sets except all select to_jsonb(t) from public.catalogue_sets t)
 or exists(select row from before_catalogue_subsets except all select to_jsonb(t) from public.catalogue_subsets t)
 or exists(select row from before_catalogue_cards except all select to_jsonb(t) from public.catalogue_cards t)
 or exists(select row from before_catalogue_variants except all select to_jsonb(t) from public.catalogue_variants t)
 or exists(select row from before_catalogue_parallel_rules except all select to_jsonb(t) from public.catalogue_parallel_rules t)
 or exists(select row from before_catalogue_sources except all select to_jsonb(t) from public.catalogue_sources t)
 or exists(select row from before_collection_items except all select to_jsonb(t) from public.collection_items t)
 or exists(select row from before_reference_images except all select to_jsonb(t) from public.reference_images t)
 or exists(select to_jsonb(t) from public.collection_items t except all select row from before_collection_items)
 or exists(select to_jsonb(t) from public.reference_images t except all select row from before_reference_images)
 then raise exception 'Count, linkage or preservation check failed'; end if;
end $$;
select 'verified' as result,(select count(*) from public.catalogue_cards) as cards,(select count(*) from public.collection_items) as collections;
commit;
